type LegacyJavaDispatch = dyn Fn(String) -> Result<String, String> + Send + Sync;
fn legacy_java_dispatch_slot() -> &'static RwLock<Option<Arc<LegacyJavaDispatch>>> {
    static SLOT: OnceLock<RwLock<Option<Arc<LegacyJavaDispatch>>>> = OnceLock::new();
    SLOT.get_or_init(|| RwLock::new(None))
}
pub fn installLegacyJavaDispatch(dispatch: Arc<LegacyJavaDispatch>) {
    *legacy_java_dispatch_slot().write().expect("legacy Java bridge lock") = Some(dispatch);
}
pub fn nativeLegacyJavaDispatchString(request: String) -> String {
    let dispatch = legacy_java_dispatch_slot().read().expect("legacy Java bridge lock").clone();
    match dispatch {
        Some(dispatch) => dispatch(request).unwrap_or_else(|error| javaBridgeFailure(&error)),
        None => javaBridgeFailure("Android Java host is not available on this platform"),
    }
