pub struct LegacyJavaScope { id: String }
impl LegacyJavaScope {
    pub fn new() -> Self { Self { id: uuid::Uuid::new_v4().to_string() } }
    pub fn dispatch(&self, request: String) -> String {
        match serde_json::from_str::<Value>(&request) {
            Ok(mut value) => {
                value["scope"] = Value::String(self.id.clone());
                nativeLegacyJavaDispatchString(value.to_string())
            }
            Err(error) => javaBridgeFailure(&error.to_string()),
        }
    }
}
impl Drop for LegacyJavaScope {
    fn drop(&mut self) {
        let _ = nativeLegacyJavaDispatchString(serde_json::json!({"operation":"releaseScope","scope":self.id}).to_string());
    }
}

