/// Returns the dependency set associated with this handler.

/// Makes plugin CLI calls operate on this application, not a separately initialized runtime.
#[cfg(not(target_arch = "wasm32"))]
pub fn bindLocalCoreCommandExecutor(&mut self) -> Result<(), String> {
    let toolHandler = self.localApplicationMut().toolHandler.clone();
    let weakApplication = Arc::downgrade(&self.application);
    let executor: operit_host_api::HostManager::CoreCommandExecutor = Arc::new(move |args| {
        let application = weakApplication.upgrade().ok_or("The local application has stopped")?;
        let (sender, receiver) = std::sync::mpsc::sync_channel(1);
        operit_host_api::HostRuntimeTaskSchedulerHost::scheduleHostRuntimeAsyncTask(
            operit_host_api::HostManager::defaultHostRuntimeTaskSchedulerHost().as_ref(),
            "plugin-core-command",
            Box::new(move || Box::pin(async move {
                let mut application = application.lock().await;
                let result = operit_command_core::run_core_command(&mut application, &args).map(|output| output.stdout);
                let _ = sender.send(result);
            })),
        ).map_err(|error| error.to_string())?;
        receiver.recv().map_err(|error| error.to_string())?
    });
    toolHandler.bindCoreCommandExecutor(executor.clone());
    self.hostManager.coreCommandExecutor = Some(executor.clone());
    self.application.try_lock().map_err(|error| error.to_string())?.hostManager.coreCommandExecutor = Some(executor);
    Ok(())
}

